INSERT INTO "public"."ai_drafts" ("id", "target_type", "target_id", "locale", "prompt_type", "prompt_input_hash", "output_json", "status", "requested_by", "reviewed_by", "created_at", "updated_at") VALUES
('035a29f5-7434-4605-bc16-71b2db919cd4', 'product', NULL, 'en', 'generate-content', NULL, '{"enBody": "<p>The <strong>\"Élégance\" Luxury Sofa</strong> from Showroom Nội Thất Phương Đông is an emblem of timeless sophistication and ultimate comfort. Every curve, every detail is meticulously crafted, reflecting our unwavering commitment to quality and refinement in every piece of luxury furniture.</p><p>The design of \"Élégance\" draws inspiration from a modern, minimalist yet undeniably grand lifestyle, effortlessly integrating into diverse interior settings, from penthouse apartments to expansive villas.</p><p><strong>Key Features:</strong></p><ul><li><strong>Exquisite Materials:</strong> A solid natural oak wood frame, treated for warp and termite resistance, ensuring superior durability. High-density foam cushioning offers optimal resilience, providing plush comfort and perfect body support.</li><li><strong>Luxurious Upholstery:</strong> A diverse selection, from premium Italian genuine leather to sumptuously soft velvet or stain-resistant technical fabrics, all exude refined beauty and a delightful tactile experience.</li><li><strong>Artisanal Craftsmanship:</strong> Every stitch is meticulously executed by skilled artisans, guaranteeing impeccable finish and enduring quality over time.</li><li><strong>Versatile Design:</strong> Customizable dimensions and configurations to perfectly suit any space and usage requirement.</li></ul><p>With \"Élégance,\" you acquire not just a sofa, but a masterpiece, elevating your living space to an echelon of luxury where every moment of relaxation becomes a premium experience.</p>", "enSlug": "elegance-luxury-sofa", "viBody": "<p><strong>Ghế Sofa \"Élégance\"</strong> từ Showroom Nội Thất Phương Đông là biểu tượng của sự sang trọng vượt thời gian và sự thoải mái tuyệt đối. Mỗi đường nét, mỗi chi tiết đều được chế tác tỉ mỉ, phản ánh cam kết của chúng tôi về chất lượng và sự tinh xảo trong từng sản phẩm nội thất cao cấp.</p><p>Thiết kế của \"Élégance\" lấy cảm hứng từ phong cách sống hiện đại, tối giản nhưng không kém phần đẳng cấp, dễ dàng hòa nhập vào nhiều không gian nội thất, từ căn hộ penthouse tới biệt thự rộng lớn.</p><p><strong>Đặc điểm nổi bật:</strong></p><ul><li><strong>Chất liệu Tuyệt Hảo:</strong> Khung gỗ sồi tự nhiên được xử lý chống cong vênh, mối mọt, đảm bảo độ bền vượt trội. Đệm mút cao cấp có độ đàn hồi tối ưu, mang lại cảm giác êm ái, nâng đỡ cơ thể hoàn hảo.</li><li><strong>Vải Bọc Sang Trọng:</strong> Lựa chọn đa dạng từ da thật Italia cao cấp, vải nhung mềm mại hay vải dệt công nghệ chống bám bẩn, tất cả đều toát lên vẻ đẹp tinh tế và cảm giác chạm dễ chịu.</li><li><strong>Thủ Công Tinh Xảo:</strong> Từng đường kim mũi chỉ được thực hiện bởi những nghệ nhân lành nghề, đảm bảo độ hoàn thiện sắc nét và bền bỉ theo thời gian.</li><li><strong>Thiết Kế Đa Năng:</strong> Có thể tùy chỉnh kích thước và cấu hình để phù hợp với mọi không gian và nhu cầu sử dụng.</li></ul><p>Với \"Élégance\", bạn không chỉ sở hữu một chiếc ghế sofa mà còn là một tác phẩm nghệ thuật, mang đến không gian sống đẳng cấp, nơi mọi khoảnh khắc thư giãn đều trở thành trải nghiệm thượng lưu.</p>", "viSlug": "ghe-sofa-cao-cap-elegance", "enTitle": "\"Élégance\" Luxury Sofa", "viTitle": "Ghế Sofa Cao Cấp \"Élégance\"", "enSummary": "The \"Élégance\" Luxury Sofa offers a perfect blend of sophisticated design and ultimate relaxation, redefining your opulent living space.", "seoDescEn": "Discover the \"Élégance\" Luxury Sofa: exquisite design, premium materials, and ultimate comfort. Elevate your opulent living space with Phương Đông Furniture.", "seoDescVi": "Khám phá Ghế Sofa \"Élégance\" với thiết kế tinh xảo, chất liệu cao cấp và sự thoải mái tối ưu. Nâng tầm không gian sống sang trọng của bạn với Nội Thất Phương Đông.", "viSummary": "Ghế Sofa \"Élégance\" mang đến sự kết hợp hoàn hảo giữa thiết kế tinh tế và trải nghiệm thư giãn đỉnh cao, định hình lại không gian sống sang trọng của bạn.", "seoTitleEn": "\"Élégance\" Luxury Sofa | Phương Đông Showroom", "seoTitleVi": "Ghế Sofa \"Élégance\" Cao Cấp | Nội Thất Phương Đông", "specCareEn": "<ul><li>Clean regularly with a soft dry or slightly damp cloth.</li><li>Avoid direct exposure to harsh sunlight and high heat sources.</li><li>Use recommended specialized cleaning solutions for leather/fabric upholstery.</li><li>Periodically check and tighten screws (if applicable).</li><li>Do not place sharp objects on the sofa surface.</li></ul>", "specCareVi": "<ul><li>Vệ sinh định kỳ bằng khăn mềm khô hoặc ẩm nhẹ.</li><li>Tránh tiếp xúc trực tiếp với ánh nắng mặt trời gắt và nguồn nhiệt cao.</li><li>Sử dụng dung dịch vệ sinh chuyên dụng cho da/vải bọc theo khuyến nghị.</li><li>Kiểm tra và siết chặt ốc vít định kỳ (nếu có).</li><li>Không đặt vật sắc nhọn lên bề mặt sofa.</li></ul>", "materialsEn": "Solid natural oak wood frame, high-density foam, elastic springs, upholstered in premium Italian genuine leather / velvet / high-grade woven fabric.", "materialsVi": "Khung gỗ sồi tự nhiên, đệm mút cao cấp, lò xo đàn hồi, bọc da thật Italia / vải nhung / vải dệt cao cấp.", "dimensionsEn": "2800 x 1000 x 750 mm (Length x Depth x Height)", "dimensionsVi": "2800 x 1000 x 750 mm (Dài x Rộng x Cao)", "specFinishEn": "<ul><li><strong>Wood Finish:</strong> 5-layer premium PU coating, smooth surface, long-lasting color, light scratch resistance.</li><li><strong>Stitching:</strong> Exquisite, straight, robust, utilizing specialized threads for luxury furniture.</li><li><strong>Sofa Legs:</strong> Gold-plated alloy or stainless steel, corrosion-resistant, adding a luxurious accent.</li></ul>", "specFinishVi": "<ul><li><strong>Hoàn Thiện Gỗ:</strong> Sơn PU 5 lớp cao cấp, bề mặt mịn màng, bền màu, chống trầy xước nhẹ.</li><li><strong>Đường May:</strong> Tinh xảo, thẳng đều, chắc chắn, sử dụng chỉ chuyên dụng cho nội thất cao cấp.</li><li><strong>Chân Sofa:</strong> Hợp kim mạ vàng hoặc thép không gỉ, chống ăn mòn, tạo điểm nhấn sang trọng.</li></ul>", "specMaterialEn": "<ul><li><strong>Frame:</strong> Solid natural oak wood, treated for warp, termite, and moisture resistance to standard specifications.</li><li><strong>Cushioning:</strong> High-density D40/D50 premium foam with high resilience, anti-sagging properties, combined with individual pocket springs.</li><li><strong>Upholstery:</strong> Imported Italian genuine cowhide leather (thickness 1.3-1.5mm) or Belgian/Turkish velvet/woven fabric, featuring light water resistance and easy-to-clean properties.</li></ul>", "specMaterialVi": "<ul><li><strong>Khung:</strong> Gỗ sồi tự nhiên đã qua xử lý chống cong vênh, mối mọt, độ ẩm tiêu chuẩn.</li><li><strong>Đệm:</strong> Mút cao cấp D40/D50 với độ đàn hồi cao, không xẹp lún, kết hợp lò xo túi độc lập.</li><li><strong>Vải Bọc:</strong> Da bò thật nhập khẩu từ Ý (độ dày 1.3-1.5mm) hoặc vải nhung/dệt từ Bỉ/Thổ Nhĩ Kỳ, có khả năng chống thấm nhẹ và dễ vệ sinh.</li></ul>"}', 'draft', '73707f63-8320-442a-8bd5-1ae509130547', NULL, '2026-06-30 17:04:49.940705+00', '2026-06-30 17:04:49.940705+00');
