INSERT INTO "public"."blog_post_translations" ("id", "post_id", "locale", "slug", "title", "excerpt", "body_json", "seo_title", "seo_description", "og_image_media_id", "search_text", "created_at", "updated_at") VALUES
('d7a3b661-d914-474d-ac39-7b4189a46ef4', '432e17ea-eaea-4029-9b60-bed02498d1c9', 'vi', 'bi-quyet-chon-go-oc-cho', 'Bí quyết chọn gỗ óc chó cho nội thất bền vững', 'Nhận biết vân gỗ, độ ẩm và quy trình xử lý bề mặt trước khi đầu tư.', '{"quote": {"en": "A good wooden piece is not only beautiful on handover day; it should keep pace with family life for years.", "vi": "Một món đồ gỗ tốt không chỉ đẹp ở ngày bàn giao; nó phải giữ được nhịp sống của gia đình trong nhiều năm."}, "sections": [{"id": "nguon-goc", "body": {"en": "Premium walnut should come with clear sourcing, drying and moisture control information. When seasonal humidity changes, unstable material can warp, crack or shift color after use.", "vi": "Gỗ óc chó cao cấp cần có hồ sơ nguồn gốc, thông tin sấy và kiểm soát độ ẩm rõ ràng. Khi khí hậu thay đổi theo mùa, vật liệu chưa ổn định dễ cong vênh, nứt chân chim hoặc lệch màu sau một thời gian sử dụng."}, "title": {"en": "Start with sourcing and stability", "vi": "Bắt đầu từ nguồn gốc và độ ổn định"}}, {"id": "van-go", "body": {"en": "Beautiful grain has a natural rhythm, not a patched look. On large tables, cabinets or wall panels, grain matching and board joining define the premium feel of the entire space.", "vi": "Vân gỗ đẹp phải có nhịp điệu tự nhiên, không bị ghép vá thiếu chủ đích. Với các bề mặt lớn như bàn, tủ hoặc vách, cách đảo vân và nối tấm quyết định cảm giác cao cấp của toàn bộ không gian."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424088/showroom/woodWall.png", "title": {"en": "Read the grain as a design layer", "vi": "Đọc vân gỗ như một lớp thiết kế"}}, {"id": "hoan-thien", "body": {"en": "A good finish balances touch, durability and maintainability. Inspect edges, corners, backs, runners and hidden details because they reveal craft and production standards.", "vi": "Một lớp hoàn thiện tốt cân bằng giữa cảm giác chạm, độ bền và khả năng bảo trì. Hãy kiểm tra cạnh, góc, mặt sau, ray trượt và những chi tiết ít thấy, vì đó là nơi thể hiện tay nghề và tiêu chuẩn sản xuất."}, "title": {"en": "Finishing must serve real living", "vi": "Bề mặt hoàn thiện phải phục vụ đời sống thật"}}, {"id": "showroom", "body": {"en": "Material samples should be viewed beside stone, tile, lighting and accompanying fixtures. In the showroom, consultants can compare samples for tone, proportion and budget before planning.", "vi": "Mẫu vật liệu cần được xem cạnh đá, gạch, ánh sáng và thiết bị đi kèm. Tại showroom, đội ngũ tư vấn có thể đặt các mẫu cạnh nhau để kiểm tra tông màu, tỷ lệ và ngân sách trước khi lên phương án."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424086/showroom/showroom.jpg", "title": {"en": "Compare directly in the showroom", "vi": "So sánh trực tiếp tại showroom"}}], "takeaways": ["Ưu tiên nguồn gỗ rõ ràng, độ ẩm ổn định và quy trình sấy phù hợp khí hậu Việt Nam.", "Quan sát vân gỗ, màu sắc và độ hoàn thiện dưới ánh sáng tự nhiên lẫn ánh sáng showroom.", "Yêu cầu tư vấn bảo hành, chăm sóc bề mặt và điều kiện lắp đặt trước khi chốt vật liệu."]}', 'Bí quyết chọn gỗ óc chó', 'Bí quyết chọn gỗ óc chó cho nội thất', NULL, '''am'':17 ''be'':23 ''ben'':10 ''bi'':1,29,35 ''biet'':13 ''cho'':6,7,34,40,41 ''chon'':3,31,37 ''dau'':27 ''do'':16 ''go'':4,15,32,38 ''khi'':26 ''ly'':22 ''mat'':24 ''nhan'':12 ''noi'':8,42 ''oc'':5,33,39 ''quy'':19 ''quyet'':2,30,36 ''that'':9,43 ''trinh'':20 ''truoc'':25 ''tu'':28 ''va'':18 ''van'':14 ''vung'':11 ''xu'':21', '2026-06-25 14:46:10.668016+00', '2026-06-25 14:46:10.668016+00'),
('838dbc7f-5e25-418f-a27c-47898ba57ca2', '432e17ea-eaea-4029-9b60-bed02498d1c9', 'en', 'bi-quyet-chon-go-oc-cho', 'How to choose walnut wood for lasting interiors', 'Understand grain, moisture and finishing process before investing.', '{"quote": {"en": "A good wooden piece is not only beautiful on handover day; it should keep pace with family life for years.", "vi": "Một món đồ gỗ tốt không chỉ đẹp ở ngày bàn giao; nó phải giữ được nhịp sống của gia đình trong nhiều năm."}, "sections": [{"id": "nguon-goc", "body": {"en": "Premium walnut should come with clear sourcing, drying and moisture control information. When seasonal humidity changes, unstable material can warp, crack or shift color after use.", "vi": "Gỗ óc chó cao cấp cần có hồ sơ nguồn gốc, thông tin sấy và kiểm soát độ ẩm rõ ràng. Khi khí hậu thay đổi theo mùa, vật liệu chưa ổn định dễ cong vênh, nứt chân chim hoặc lệch màu sau một thời gian sử dụng."}, "title": {"en": "Start with sourcing and stability", "vi": "Bắt đầu từ nguồn gốc và độ ổn định"}}, {"id": "van-go", "body": {"en": "Beautiful grain has a natural rhythm, not a patched look. On large tables, cabinets or wall panels, grain matching and board joining define the premium feel of the entire space.", "vi": "Vân gỗ đẹp phải có nhịp điệu tự nhiên, không bị ghép vá thiếu chủ đích. Với các bề mặt lớn như bàn, tủ hoặc vách, cách đảo vân và nối tấm quyết định cảm giác cao cấp của toàn bộ không gian."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424088/showroom/woodWall.png", "title": {"en": "Read the grain as a design layer", "vi": "Đọc vân gỗ như một lớp thiết kế"}}, {"id": "hoan-thien", "body": {"en": "A good finish balances touch, durability and maintainability. Inspect edges, corners, backs, runners and hidden details because they reveal craft and production standards.", "vi": "Một lớp hoàn thiện tốt cân bằng giữa cảm giác chạm, độ bền và khả năng bảo trì. Hãy kiểm tra cạnh, góc, mặt sau, ray trượt và những chi tiết ít thấy, vì đó là nơi thể hiện tay nghề và tiêu chuẩn sản xuất."}, "title": {"en": "Finishing must serve real living", "vi": "Bề mặt hoàn thiện phải phục vụ đời sống thật"}}, {"id": "showroom", "body": {"en": "Material samples should be viewed beside stone, tile, lighting and accompanying fixtures. In the showroom, consultants can compare samples for tone, proportion and budget before planning.", "vi": "Mẫu vật liệu cần được xem cạnh đá, gạch, ánh sáng và thiết bị đi kèm. Tại showroom, đội ngũ tư vấn có thể đặt các mẫu cạnh nhau để kiểm tra tông màu, tỷ lệ và ngân sách trước khi lên phương án."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424086/showroom/showroom.jpg", "title": {"en": "Compare directly in the showroom", "vi": "So sánh trực tiếp tại showroom"}}], "takeaways": ["Prioritize clear sourcing, stable moisture and drying suitable for Vietnamese climate.", "Check grain, color and finishing under both daylight and showroom lighting.", "Confirm warranty, surface care and installation conditions before finalizing materials."]}', 'How to choose walnut wood', 'How to choose walnut wood for interiors', NULL, '''and'':12 ''before'':15 ''choose'':3,19,24 ''finishing'':13 ''for'':6,27 ''grain'':10 ''how'':1,17,22 ''interiors'':8,28 ''investing'':16 ''lasting'':7 ''moisture'':11 ''process'':14 ''to'':2,18,23 ''understand'':9 ''walnut'':4,20,25 ''wood'':5,21,26', '2026-06-25 14:46:10.668016+00', '2026-06-25 14:46:10.668016+00'),
('115b8cfb-7522-4919-a4ce-363b30c129bf', 'c5c83364-1d5a-40d0-a906-5fc62e860c98', 'vi', 'xu-huong-phong-tam-2026', 'Xu hướng phòng tắm khách sạn trong nhà ở hiện đại', 'Các lớp vật liệu, ánh sáng và phụ kiện giúp phòng tắm trở thành nghỉ dưỡng.', '{"quote": {"en": "A good bathroom feels like a small suite: quiet, easy to maintain and restorative every day.", "vi": "Phòng tắm tốt giống một suite nhỏ: yên tĩnh, dễ chăm sóc và tạo cảm giác nghỉ ngơi mỗi ngày."}, "sections": [{"id": "wellness", "body": {"en": "Thermostatic showers, freestanding tubs, anti-scale surfaces and soft lighting are turning bathrooms into places to recover after long days.", "vi": "Sen tắm nhiệt, bồn tắm độc lập, bề mặt chống bám cặn và ánh sáng dịu đang giúp phòng tắm trở thành không gian hồi phục năng lượng sau ngày dài."}, "title": {"en": "Wellness becomes the new standard", "vi": "Wellness trở thành tiêu chuẩn mới"}}, {"id": "vat-lieu", "body": {"en": "Stone, large-format tile, moisture-resistant wood and warm metal can work together when tone and reflectivity are controlled.", "vi": "Đá, gạch khổ lớn, gỗ chịu ẩm và kim loại ấm có thể phối cùng nhau nếu kiểm soát đúng tông màu và độ phản chiếu."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424091/showroom/room.jpg", "title": {"en": "Material layers create depth", "vi": "Lớp vật liệu tạo chiều sâu"}}, {"id": "lap-dat", "body": {"en": "Floor drains, tap height, water pressure and expansion joints should be checked early to prevent installation issues.", "vi": "Vị trí thoát sàn, chiều cao vòi, áp lực nước và khe co giãn cần được kiểm tra sớm để tránh phát sinh khi lắp đặt."}, "title": {"en": "Technical planning comes first", "vi": "Thiết kế kỹ thuật phải đi trước"}}], "takeaways": ["Phòng tắm cao cấp đang chuyển từ chức năng thuần túy sang trải nghiệm wellness tại nhà.", "Ánh sáng, lớp vật liệu và thiết bị tiết kiệm nước quyết định cảm giác sử dụng hằng ngày.", "Nên chốt thiết bị chính trước khi hoàn thiện đường nước, điện và bề mặt ốp lát."]}', 'Xu hướng phòng tắm khách sạn', 'Xu hướng phòng tắm khách sạn 2026', NULL, '''2026'':40 ''anh'':16 ''cac'':12 ''dai'':11 ''duong'':27 ''giup'':21 ''hien'':10 ''huong'':2,29,35 ''khach'':5,32,38 ''kien'':20 ''lieu'':15 ''lop'':13 ''nghi'':26 ''nha'':8 ''o'':9 ''phong'':3,22,30,36 ''phu'':19 ''san'':6,33,39 ''sang'':17 ''tam'':4,23,31,37 ''thanh'':25 ''tro'':24 ''trong'':7 ''va'':18 ''vat'':14 ''xu'':1,28,34', '2026-06-25 14:46:10.668016+00', '2026-06-25 14:46:10.668016+00'),
('8f6ac3a5-a75e-499c-90a7-b0de7dcbad29', 'c5c83364-1d5a-40d0-a906-5fc62e860c98', 'en', 'xu-huong-phong-tam-2026', 'Hotel-inspired bathroom trends for modern homes', 'Material layers, lighting and accessories that turn bathrooms into wellness spaces.', '{"quote": {"en": "A good bathroom feels like a small suite: quiet, easy to maintain and restorative every day.", "vi": "Phòng tắm tốt giống một suite nhỏ: yên tĩnh, dễ chăm sóc và tạo cảm giác nghỉ ngơi mỗi ngày."}, "sections": [{"id": "wellness", "body": {"en": "Thermostatic showers, freestanding tubs, anti-scale surfaces and soft lighting are turning bathrooms into places to recover after long days.", "vi": "Sen tắm nhiệt, bồn tắm độc lập, bề mặt chống bám cặn và ánh sáng dịu đang giúp phòng tắm trở thành không gian hồi phục năng lượng sau ngày dài."}, "title": {"en": "Wellness becomes the new standard", "vi": "Wellness trở thành tiêu chuẩn mới"}}, {"id": "vat-lieu", "body": {"en": "Stone, large-format tile, moisture-resistant wood and warm metal can work together when tone and reflectivity are controlled.", "vi": "Đá, gạch khổ lớn, gỗ chịu ẩm và kim loại ấm có thể phối cùng nhau nếu kiểm soát đúng tông màu và độ phản chiếu."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424091/showroom/room.jpg", "title": {"en": "Material layers create depth", "vi": "Lớp vật liệu tạo chiều sâu"}}, {"id": "lap-dat", "body": {"en": "Floor drains, tap height, water pressure and expansion joints should be checked early to prevent installation issues.", "vi": "Vị trí thoát sàn, chiều cao vòi, áp lực nước và khe co giãn cần được kiểm tra sớm để tránh phát sinh khi lắp đặt."}, "title": {"en": "Technical planning comes first", "vi": "Thiết kế kỹ thuật phải đi trước"}}], "takeaways": ["Premium bathrooms are moving from pure function toward at-home wellness experiences.", "Lighting, material layers and water-efficient fixtures define daily comfort.", "Confirm key fixtures before finalizing plumbing, electrical and tile surfaces."]}', 'Hotel-inspired bathroom trends', 'Hotel-inspired bathroom trends', NULL, '''accessories'':13 ''and'':12 ''bathroom'':4,23,28 ''bathrooms'':16 ''for'':6 ''homes'':8 ''hotel'':2,21,26 ''hotel-inspired'':1,20,25 ''inspired'':3,22,27 ''into'':17 ''layers'':10 ''lighting'':11 ''material'':9 ''modern'':7 ''spaces'':19 ''that'':14 ''trends'':5,24,29 ''turn'':15 ''wellness'':18', '2026-06-25 14:46:10.668016+00', '2026-06-25 14:46:10.668016+00'),
('777e4004-083d-45e2-96ff-8906573c7155', '01359dcc-0dcd-435a-9642-a0cf99acc255', 'vi', 'phoi-gach-go-va-da', 'Phối gạch, gỗ và đá để không gian có chiều sâu', 'Cách cân bằng bề mặt lạnh và ấm để không gian sang trọng nhưng vẫn gần gũi.', '{"quote": {"en": "Luxury does not come from the most expensive material, but from surfaces that listen to each other.", "vi": "Sang trọng không đến từ vật liệu đắt nhất, mà từ cách các bề mặt lắng nghe nhau."}, "sections": [{"id": "bang-vat-lieu", "body": {"en": "Choose one primary surface, one accent surface and one background surface. This hierarchy adds depth without visual noise.", "vi": "Hãy chọn một bề mặt chính, một bề mặt nhấn và một bề mặt nền. Cách phân vai này giúp không gian có chiều sâu mà không bị rối."}, "title": {"en": "Build the palette in layers", "vi": "Xây bảng vật liệu theo lớp"}}, {"id": "ti-le", "body": {"en": "Wood can warm stone, while light tile balances darker planes. The key is controlling how much of each material appears in the main view.", "vi": "Gỗ có thể làm ấm đá, còn gạch sáng giúp cân bằng mảng tối. Điều quan trọng là kiểm soát diện tích từng vật liệu trong trường nhìn chính."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424090/showroom/texture.jpg", "title": {"en": "Proportion matters more than quantity", "vi": "Tỷ lệ quan trọng hơn số lượng"}}, {"id": "anh-sang", "body": {"en": "The same stone or tile can shift under warm, cool or daylight conditions. Samples should be reviewed at multiple times before approval.", "vi": "Cùng một mẫu đá hoặc gạch có thể đổi sắc dưới ánh sáng vàng, trắng hoặc ánh sáng tự nhiên. Mẫu nên được xem tại nhiều thời điểm trước khi chốt."}, "title": {"en": "Test under real lighting", "vi": "Kiểm tra dưới ánh sáng thật"}}], "takeaways": ["Một bảng vật liệu tốt cần có điểm ấm, điểm lạnh và bề mặt trung hòa để tạo chiều sâu.", "Không nên phối quá nhiều vân mạnh trong cùng một trường nhìn.", "Ánh sáng quyết định cách gạch, gỗ và đá đọc màu trong không gian thật."]}', 'Phối gạch gỗ và đá', 'Phối gạch gỗ và đá', NULL, '''am'':19 ''bang'':14 ''be'':15 ''cach'':12 ''can'':13 ''chieu'':10 ''co'':9 ''da'':5,33,38 ''de'':6,20 ''gach'':2,30,35 ''gan'':27 ''gian'':8,22 ''go'':3,31,36 ''gui'':28 ''khong'':7,21 ''lanh'':17 ''mat'':16 ''nhung'':25 ''phoi'':1,29,34 ''sang'':23 ''sau'':11 ''trong'':24 ''va'':4,18,32,37 ''van'':26', '2026-06-25 14:46:10.668016+00', '2026-06-25 14:46:10.668016+00'),
('2661df73-c053-4e2d-b70a-edb78c02679e', '01359dcc-0dcd-435a-9642-a0cf99acc255', 'en', 'phoi-gach-go-va-da', 'Combining tile, wood and stone for visual depth', 'Balance cool and warm surfaces to keep spaces premium yet welcoming.', '{"quote": {"en": "Luxury does not come from the most expensive material, but from surfaces that listen to each other.", "vi": "Sang trọng không đến từ vật liệu đắt nhất, mà từ cách các bề mặt lắng nghe nhau."}, "sections": [{"id": "bang-vat-lieu", "body": {"en": "Choose one primary surface, one accent surface and one background surface. This hierarchy adds depth without visual noise.", "vi": "Hãy chọn một bề mặt chính, một bề mặt nhấn và một bề mặt nền. Cách phân vai này giúp không gian có chiều sâu mà không bị rối."}, "title": {"en": "Build the palette in layers", "vi": "Xây bảng vật liệu theo lớp"}}, {"id": "ti-le", "body": {"en": "Wood can warm stone, while light tile balances darker planes. The key is controlling how much of each material appears in the main view.", "vi": "Gỗ có thể làm ấm đá, còn gạch sáng giúp cân bằng mảng tối. Điều quan trọng là kiểm soát diện tích từng vật liệu trong trường nhìn chính."}, "image": "https://res.cloudinary.com/dcmhbxcgq/image/upload/v1781424090/showroom/texture.jpg", "title": {"en": "Proportion matters more than quantity", "vi": "Tỷ lệ quan trọng hơn số lượng"}}, {"id": "anh-sang", "body": {"en": "The same stone or tile can shift under warm, cool or daylight conditions. Samples should be reviewed at multiple times before approval.", "vi": "Cùng một mẫu đá hoặc gạch có thể đổi sắc dưới ánh sáng vàng, trắng hoặc ánh sáng tự nhiên. Mẫu nên được xem tại nhiều thời điểm trước khi chốt."}, "title": {"en": "Test under real lighting", "vi": "Kiểm tra dưới ánh sáng thật"}}], "takeaways": ["A strong material palette needs warmth, coolness and neutral surfaces for depth.", "Avoid combining too many strong grains or veins in the same sightline.", "Lighting determines how tile, wood and stone read in the real space."]}', 'Combining tile wood and stone', 'Combining tile wood and stone', NULL, '''and'':4,11,23,28 ''balance'':9 ''combining'':1,20,25 ''cool'':10 ''depth'':8 ''for'':6 ''keep'':15 ''premium'':17 ''spaces'':16 ''stone'':5,24,29 ''surfaces'':13 ''tile'':2,21,26 ''to'':14 ''visual'':7 ''warm'':12 ''welcoming'':19 ''wood'':3,22,27 ''yet'':18', '2026-06-25 14:46:10.668016+00', '2026-06-25 14:46:10.668016+00'),
