('a4211988-3399-486b-a8de-cef680480a44', 'f7646453-b14f-436e-93a7-6b7598bb7c7d', 'vi', 'ban-an-go-soi-keo-gian-luxury', 'Bàn ăn gỗ sồi kéo giãn Luxury', 'Bàn ăn kéo giãn từ gỗ sồi tự nhiên, thiết kế thông minh.', '"<p>Nội dung chi tiết sản phẩm bàn ăn gỗ sồi kéo giãn</p>"', NULL, '0 VND', NULL, 'Bàn ăn gỗ sồi kéo giãn Luxury cao cấp', 'Bàn ăn kéo giãn nhập khẩu từ gỗ sồi tự nhiên cao cấp', NULL, '''0'':21 ''an'':2,9 ''ban'':1,8 ''gian'':6,11 ''go'':3,13 ''ke'':18 ''keo'':5,10 ''luxury'':7 ''minh'':20 ''nhien'':16 ''soi'':4,14 ''thiet'':17 ''thong'':19 ''tu'':12,15 ''vnd'':22', '2026-07-01 14:04:18.311836+00', '2026-07-01 14:04:18.311836+00'),
('46d45186-401f-49ce-8727-d855f62306a4', '00000001-0000-0000-0000-000000000012', 'vi', 'sofa-da-bo-y-3-cho-ngoi', 'Sofa Da Bò Ý 3 Chỗ Ngồi', 'Sofa 3 chỗ bọc da bò Ý full aniline màu cognac ấm áp, chân inox mờ tinh tế.', '{"en": "Fully upholstered in soft Italian full-aniline leather. High-density polyurethane foam cushioning. Chrome metal legs.", "vi": "Bọc toàn bộ bằng da bò ý full aniline mềm mịn và thấm hút tự nhiên. Lõi mút Polyurethane 35kg/m³ chuẩn cao cấp. Chân kim loại chrome."}', 'Da bò Ý full aniline, Khung gỗ sồi', '62,000,000 VND', '2200 x 900 x 790 mm', NULL, NULL, NULL, '''000'':35,36 ''2200'':38 ''3'':5,9 ''62'':34 ''790'':42 ''900'':40 ''am'':19 ''aniline'':16,30 ''ap'':20 ''bo'':3,13,27 ''boc'':11 ''chan'':21 ''cho'':6,10 ''cognac'':18 ''da'':2,12,26 ''full'':15,29 ''go'':32 ''inox'':22 ''khung'':31 ''mau'':17 ''mm'':43 ''mo'':23 ''ngoi'':7 ''sofa'':1,8 ''soi'':33 ''te'':25 ''tinh'':24 ''vnd'':37 ''x'':39,41 ''y'':4,14,28', '2026-06-30 12:30:00.846972+00', '2026-07-01 12:02:52.797135+00'),
('66b032cd-2596-4731-8284-364a67adc74a', '00000001-0000-0000-0000-000000000014', 'vi', 'ke-tivi-go-soi-tu-nhien-nordic', 'Kệ Tivi Gỗ Sồi Tự Nhiên Nordic', 'Kệ tivi tối giản phong cách Bắc Âu gỗ sồi tự nhiên, ngăn kéo giảm chấn Blum, chân gỗ côn thanh lịch.', '{"en": "Elegant minimalist Nordic design. Natural oak treated with natural oil for durability. Blum soft-close drawer system.", "vi": "Thiết kế tối giản tinh tế mang phong cách Nordic. Gỗ sồi tự nhiên xử lý dầu tự nhiên bền màu. Ngăn kéo giảm chấn Blum êm ái."}', 'Gỗ sồi tự nhiên, Phụ kiện Blum (Đức)', '24,000,000 VND', '1600 x 450 x 500 mm', NULL, NULL, NULL, '''000'':39,40 ''1600'':42 ''24'':38 ''450'':44 ''500'':46 ''au'':15 ''bac'':14 ''blum'':24,36 ''cach'':13 ''chan'':23,25 ''con'':27 ''duc'':37 ''giam'':22 ''gian'':11 ''go'':3,16,26,30 ''ke'':1,8 ''keo'':21 ''kien'':35 ''lich'':29 ''mm'':47 ''ngan'':20 ''nhien'':6,19,33 ''nordic'':7 ''phong'':12 ''phu'':34 ''soi'':4,17,31 ''thanh'':28 ''tivi'':2,9 ''toi'':10 ''tu'':5,18,32 ''vnd'':41 ''x'':43,45', '2026-06-30 12:30:00.846972+00', '2026-07-01 12:02:52.839733+00'),
('92ea7bec-7b22-48a0-bd5d-43281d9901af', '00000001-0000-0000-0000-000000000015', 'vi', 'ban-an-walnut-live-edge-nguyen-tam', 'Bàn Ăn Walnut Live Edge Nguyên Tấm', 'Bàn ăn nguyên tấm gỗ óc chó Bắc Mỹ live edge, vân gỗ tự nhiên nghệ thuật, chân thép đen sơn tĩnh điện.', '{"en": "Single slab live edge walnut from certified North American walnut forests. H-frame powder-coated matte black steel legs.", "vi": "Mặt bàn live edge tự nhiên nguyên tấm từ rừng óc chó Bắc Mỹ được kiểm định chất lượng. Chân thép chữ H sơn tĩnh điện đen mờ."}', 'Gỗ óc chó Bắc Mỹ nguyên tấm, Thép đen sơn tĩnh điện', '54,000,000 VND', '2400 x 950 x 750 mm', NULL, NULL, NULL, '''000'':44,45 ''2400'':47 ''54'':43 ''750'':51 ''950'':49 ''an'':2,9 ''bac'':15,34 ''ban'':1,8 ''chan'':25 ''cho'':14,33 ''den'':27,39 ''dien'':30,42 ''edge'':5,18 ''go'':12,20,31 ''live'':4,17 ''mm'':52 ''my'':16,35 ''nghe'':23 ''nguyen'':6,10,36 ''nhien'':22 ''oc'':13,32 ''son'':28,40 ''tam'':7,11,37 ''thep'':26,38 ''thuat'':24 ''tinh'':29,41 ''tu'':21 ''van'':19 ''vnd'':46 ''walnut'':3 ''x'':48,50', '2026-06-30 12:30:00.846972+00', '2026-07-01 12:02:52.855507+00'),
('ed81ca96-b91c-4bd1-b4a1-2e1ab62fcaf8', 'b31b0e45-f8a7-4518-ab29-bafa6995ebe1', 'en', 'san-pham-hop-le', 'Valid Product', 'Valid summary', '{}', 'Wood', NULL, 'W100', NULL, NULL, NULL, '''product'':2 ''summary'':4 ''valid'':1,3 ''w100'':6 ''wood'':5', '2026-07-01 08:15:46.957047+00', '2026-07-01 12:33:41.70939+00'),
('00eddb85-4cfb-4085-9693-ca664c04d89e', '00000001-0000-0000-0000-000000000012', 'en', 'sofa-da-bo-y-3-cho-ngoi', 'Italian Aniline Leather 3-Seater Sofa', '3-seater sofa fully upholstered in warm cognac Italian full-aniline leather with matte chrome legs.', '{"en": "Fully upholstered in soft Italian full-aniline leather. High-density polyurethane foam cushioning. Chrome metal legs.", "vi": "Bọc toàn bộ bằng da bò ý full aniline mềm mịn và thấm hút tự nhiên. Lõi mút Polyurethane 35kg/m³ chuẩn cao cấp. Chân kim loại chrome."}', 'Italian Full-aniline Leather, Oak Frame', '62,000,000 VND', '2200 x 900 x 790 mm', NULL, NULL, NULL, '''000'':32,33 ''2200'':35 ''3'':4,7 ''62'':31 ''790'':39 ''900'':37 ''aniline'':2,18,27 ''chrome'':22 ''cognac'':14 ''frame'':30 ''full'':17,26 ''full-aniline'':16,25 ''fully'':10 ''in'':12 ''italian'':1,15,24 ''leather'':3,19,28 ''legs'':23 ''matte'':21 ''mm'':40 ''oak'':29 ''seater'':5,8 ''sofa'':6,9 ''upholstered'':11 ''vnd'':34 ''warm'':13 ''with'':20 ''x'':36,38', '2026-06-30 12:30:00.846972+00', '2026-07-01 12:33:41.70939+00'),
('ca0d3269-b365-4299-aefe-4bd6837a0552', '00000001-0000-0000-0000-000000000011', 'vi', 'sofa-curve-velour-heritage', 'Sofa Curve Velour Heritage', 'Sofa gỗ óc chó khung nguyên tấm, bọc nỉ velour nhập khẩu Bỉ cao cấp với đường chỉ thủ công tinh tế.', '{"en": "Heritage Curve Velour sofa in modern Scandinavian style. Solid walnut wood frame. Premium Belgian velour fabric, wrinkle-resistant.", "vi": "Sofa Heritage Curve Velour được thiết kế theo phong cách Bắc Âu hiện đại. Khung gỗ óc chó tự nhiên nguyên tấm vững chắc. Mặt nỉ velour nhập khẩu Bỉ mềm mịn, chống nhàu vượt trội."}', 'Khung gỗ óc chó Bắc Mỹ, Nỉ Velour Bỉ', '45,000,000 VND', '2400 x 950 x 830 mm', NULL, NULL, NULL, NULL, '2026-06-30 12:30:00.846972+00', '2026-06-30 12:30:00.846972+00'),
('7b01ca0b-db91-481b-9ede-e333170262f0', '00000001-0000-0000-0000-000000000018', 'vi', 'tu-quan-ao-kich-tran-walnut', 'Tủ Quần Áo Kịch Trần Walnut', 'Tủ quần áo kịch trần vân gỗ walnut, thanh trượt Häfele Đức êm ái, ốp kiếng sang trọng, thiết kế theo yêu cầu.', '{"en": "MDF board covered in premium North American walnut veneer. Häfele German soft-close slides. Custom sizing available.", "vi": "Gỗ MDF phủ veneer walnut Bắc Mỹ cao cấp. Thanh trượt Häfele Đức êm ái bền bỉ. Tùy chỉnh kích thước theo không gian."}', 'MDF phủ veneer Walnut, Phụ kiện Häfele Đức', '48,000,000 - 72,000,000 VND', 'Tuỳ chỉnh theo yêu cầu', NULL, NULL, NULL, NULL, '2026-06-30 12:30:00.846972+00', '2026-06-30 12:30:00.846972+00'),
('9e306ef1-50fc-4aa7-9b72-a26db2f03a1e', '00000001-0000-0000-0000-000000000021', 'vi', 'bon-tam-doc-lap-bravat-wellness', 'Bồn Tắm Độc Lập Bravat Wellness', 'Bồn tắm thân đứng Bravat Wellness Series chất liệu Solid Surface nguyên khối, giữ nhiệt suốt 2 giờ, thiết kế tối giản Đức.', '{"en": "Non-porous Solid Surface, stain-resistant, naturally antibacterial. Adjustable stainless steel feet.", "vi": "Solid Surface không thấm nước, không bám cặn, kháng khuẩn tự nhiên. Chân inox điều chỉnh được."}', 'Solid Surface, Chân inox', '65,000,000 VND', '1800 x 800 x 620 mm', NULL, NULL, NULL, NULL, '2026-06-30 12:30:00.846972+00', '2026-06-30 12:30:00.846972+00'),
('9cc905fd-5521-43f5-8592-99222233d096', '00000001-0000-0000-0000-000000000017', 'vi', 'giuong-ngu-luxury-velvet-king-size', 'Giường Ngủ Luxury Velvet King-size', 'Giường ngủ bọc nỉ nhung velvet cao cấp màu xanh đêm huyền bí, đầu giường tạo hình sóng nghệ thuật, chân gỗ cao su sơn đen.', '{"en": "Wave-shaped velvet headboard for elegant appeal. Robust frame from pine and moisture-proof board. Comfortable wooden slat system.", "vi": "Đầu giường bọc nhung velvet tạo hình làn sóng sang trọng. Khung chắc chắn từ gỗ thông và gỗ công nghiệp chống ẩm. Hệ nan gỗ êm ái."}', 'Khung gỗ thông, Vải nhung velvet', '35,000,000 VND', '1800 x 2000 mm', NULL, NULL, NULL, '''000'':41,42 ''1800'':44 ''2000'':46 ''35'':40 ''bi'':20 ''boc'':10 ''cao'':14,30 ''cap'':15 ''chan'':28 ''dau'':21 ''dem'':18 ''den'':33 ''giuong'':1,8,22 ''go'':29,35 ''hinh'':24 ''huyen'':19 ''khung'':34 ''king'':6 ''king-size'':5 ''luxury'':3 ''mau'':16 ''mm'':47 ''nghe'':26 ''ngu'':2,9 ''nhung'':12,38 ''ni'':11 ''size'':7 ''son'':32 ''song'':25 ''su'':31 ''tao'':23 ''thong'':36 ''thuat'':27 ''vai'':37 ''velvet'':4,13,39 ''vnd'':43 ''x'':45 ''xanh'':17', '2026-06-30 12:30:00.846972+00', '2026-07-01 12:02:52.885141+00'),
('2b9b24c0-ec51-4c74-a1b7-bcee9ae678e8', 'b31b0e45-f8a7-4518-ab29-bafa6995ebe1', 'vi', 'san-pham-hop-le', 'Sản phẩm hợp lệ', 'Mô tả ngắn hợp lệ', '{}', 'Gỗ', NULL, 'W100', NULL, NULL, NULL, '''go'':10 ''hop'':3,8 ''le'':4,9 ''mo'':5 ''ngan'':7 ''pham'':2 ''san'':1 ''ta'':6 ''w100'':11', '2026-07-01 08:15:46.957047+00', '2026-07-01 12:02:52.939742+00'),
('f6e5f2e1-f618-4024-8752-f13c3001d2fd', '00000001-0000-0000-0000-000000000021', 'en', 'bon-tam-doc-lap-bravat-wellness', 'Bravat Wellness Freestanding Bathtub', 'Bravat Wellness Series freestanding solid surface bathtub with 2-hour heat retention, minimalist German design.', '{"en": "Non-porous Solid Surface, stain-resistant, naturally antibacterial. Adjustable stainless steel feet.", "vi": "Solid Surface không thấm nước, không bám cặn, kháng khuẩn tự nhiên. Chân inox điều chỉnh được."}', 'Solid Surface, Stainless Steel Legs', '65,000,000 VND', '1800 x 800 x 620 mm', NULL, NULL, NULL, '''000'':26,27 ''1800'':29 ''2'':13 ''620'':33 ''65'':25 ''800'':31 ''bathtub'':4,11 ''bravat'':1,5 ''design'':19 ''freestanding'':3,8 ''german'':18 ''heat'':15 ''hour'':14 ''legs'':24 ''minimalist'':17 ''mm'':34 ''retention'':16 ''series'':7 ''solid'':9,20 ''stainless'':22 ''steel'':23 ''surface'':10,21 ''vnd'':28 ''wellness'':2,6 ''with'':12 ''x'':30,32', '2026-06-30 12:30:00.846972+00', '2026-07-01 12:32:44.029226+00'),
('5bd41f92-1348-4610-a04e-f2a1f27c1db1', '00000001-0000-0000-0000-000000000035', 'vi', 'bon-tam-american-standard-acrylic', 'Bồn Tắm American Standard Acrylic', 'Bồn tắm độc lập cao cấp American Standard thiết kế tối giản hiện đại, chất liệu acrylic nhập khẩu chống trầy vĩnh cửu.', '{"en": "Premium acrylic with heat retention, scratch and discoloration resistance. Lightweight body, easy to clean and install. Elegant oval design.", "vi": "Acrylic cao cấp nhập khẩu giữ nhiệt tốt, chống trầy và ố vàng. Thân bồn nhẹ, dễ vệ sinh và lắp đặt. Thiết kế oval thanh lịch."}', 'Acrylic cao cấp nhập khẩu', '28,000,000 VND', '1600 x 750 x 560 mm', NULL, NULL, NULL, NULL, '2026-06-30 12:30:00.846972+00', '2026-06-30 12:30:00.846972+00'),
